"""`@zuke/tally` 0.2.0: Tasks of the other shapes the tool spec must read: an object literal rather than an interface, positional JSON arguments with JSON results, an optional argument, a task named by a Python keyword, settings that run no command, and a setter that answers nothing.

Generated by ``zuke facades`` from the engine's tool spec; edit the wrapper in
zuke-build/zuke, not this file.
"""

from __future__ import annotations

from collections.abc import Callable, Sequence
from typing import Self

from zuke import ServiceContext
from zuke._facade import Settings, call, configured

PACKAGE = "tally"
VERSION = "0.2.0"


class Tuning(Settings):
    """Settings of a task that runs no command: a plain object with setters."""

    def level(self, n: float) -> Self:
        """Set the level."""
        return self._record("level", n)

    def reset(self) -> None:
        """Back to zero; answers nothing, as a setter written as a statement might."""
        self._record("reset")

class TallyTasks:
    """Plain functions of several shapes."""

    @staticmethod
    async def add(ctx: ServiceContext, a: float, b: float) -> object:
        """Add two numbers."""
        return await call(ctx, PACKAGE, VERSION, "TallyTasks", "add", [a, b])

    @staticmethod
    async def pass_(ctx: ServiceContext) -> None:
        """Do nothing, under a name Python reserves."""
        await call(ctx, PACKAGE, VERSION, "TallyTasks", "pass", [])

    @staticmethod
    async def count(ctx: ServiceContext, items: Sequence[str], skip: str | None = None) -> object:
        """Count the items, leaving out the one to skip."""
        return await call(ctx, PACKAGE, VERSION, "TallyTasks", "count", [items, skip])

    @staticmethod
    async def tune(ctx: ServiceContext, configure: Callable[[Tuning], Tuning]) -> object:
        """Tune, through settings that run nothing."""
        return await call(ctx, PACKAGE, VERSION, "TallyTasks", "tune", [configured(Tuning(), configure)])
